content:
{
  "promos": [
    {
      "title": "The Duke Returns From the Dead",
      "start_block": "B031",
      "end_block": "B058",
      "hook": "Close-up of Alexander's scarred, bearded face in a cracked mirror as he stares at his rugged reflection, then snips through his overgrown hair with heavy shears.",
      "cliffhanger": "Alexander's eyes burn with furious determination as he vows, 'And I am bringing my wife home,' and the screen cuts sharply to black.",
      "why": "A complete transformation arc in 27 seconds—from broken soldier to avenging duke—ending on a fierce vow that leaves the rescue unresolved.",
      "context_gap": "A stranger won't know Juliana is in a dungeon awaiting execution, but the vow 'bringing my wife home' implies the stakes."
    },
    {
      "title": "The Cathedral Falls to the Duke",
      "start_block": "B018",
      "end_block": "B030",
      "hook": "A royal sentry halts a horse-drawn cart with a commanding 'Stop!' and the driver meekly says 'Firewood for the kitchens, sir.'",
      "cliffhanger": "The loyalist fighter looks up at the overcast sky and says, 'Tell the Duke,' leaving the Duke's arrival and the cathedral takeover unresolved.",
      "why": "Starts with a tense checkpoint confrontation that erupts into a silent takedown, ending on a command that promises a bigger strike is coming.",
      "context_gap": "A stranger won't know who the Duke is or why the cathedral is being seized, but the covert takedown and 'Tell the Duke' line create intrigue."
    },
    {
      "title": "Enough Hiding, I Am Taking Back My House",
      "start_block": "B040",
      "end_block": "B058",
      "hook": "Alexander's deep, steely voice declares 'Enough hiding' as he traces the jagged combat scar across his cheek in the mirror.",
      "cliffhanger": "Alexander marches through the snow vowing 'And I am bringing my wife home' as his eyes burn with furious determination and the screen cuts to black.",
      "why": "Pure declaration-of-war energy—three escalating vows in 18 seconds that build to a cliffhanger cut before any rescue is shown.",
      "context_gap": "A stranger won't know who Alexander Ashwin is or what was stolen from him, but the scarred face and ducal regalia signal a reclaiming of power."
    }
  ],
  "moments": [
    {
      "start_block": "B021",
      "end_block": "B026",
      "kind": "hook",
      "description": "The cart driver lunges off the bench, tackles the royal sentry against the carriage wheel, and a second loyalist chokes the remaining guard unconscious while whispering 'Sleep.'"
    },
    {
      "start_block": "B040",
      "end_block": "B042",
      "kind": "reveal",
      "description": "Alexander declares 'Enough hiding. They buried Alexander Ashwin three years ago. Today, he comes home,' revealing his true identity as the supposedly dead Duke."
    },
    {
      "start_block": "B044",
      "end_block": "B048",
      "kind": "reveal",
      "description": "Alexander emerges in full ducal splendor—navy tailcoat, gold embroidery, lion crest—and a loyalist soldier drops to one knee in the snow, reverently saying 'Your Grace.'"
    },
    {
      "start_block": "B054",
      "end_block": "B058",
      "kind": "cliffhanger",
      "description": "Alexander roars 'No more hiding. I am taking back my house. And I am bringing my wife home,' his eyes burning with fury as the screen cuts to black."
    }
  ]
}
